      count>memory->size-offset || offset>SIZE_MAX || count>SIZE_MAX-(size_t)offset) return VK_ERROR_MEMORY_MAP_FAILED;
  return device->MapMemory(device->handle,(VkDeviceMemory)(uintptr_t)memory->handle,0,VK_WHOLE_SIZE,0,mapped);
}
